import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { Users, MapPin, Calendar, ArrowLeft, UserPlus, UserMinus, UserCheck, Flag, X, Share2, Copy, Check, Lock } from 'lucide-react';
import { io } from 'socket.io-client';
import { getApiBaseUrl } from '../utils/api';
import Chat from './Chat';

interface Participant {
  id: string;
  username: string;
  joined_at: string;
}

interface Game {
  id: string;
  title: string;
  sport: string;
  location: string;
  max_players: number;
  creator_name: string;
  created_at: string;
  is_private?: boolean;
  min_age?: number;
  is_money_game?: boolean;
  entry_fee?: number;
  total_pot?: number;
}

const GameLobby: React.FC = () => {
  const { gameId } = useParams<{ gameId: string }>();
  const navigate = useNavigate();

  const [game, setGame] = useState<Game | null>(null);
  const [participants, setParticipants] = useState<Participant[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const { user } = useAuth();
  const [showCompleteModal, setShowCompleteModal] = useState(false);
  const [results, setResults] = useState<{homeScore: string, awayScore: string}>({homeScore: '', awayScore: ''});
  const [friends, setFriends] = useState<string[]>([]);
  const [socket, setSocket] = useState<any>(null);
  const [showReportModal, setShowReportModal] = useState(false);
  const [reportingUser, setReportingUser] = useState<Participant | null>(null);
  const [reportData, setReportData] = useState({reason: '', description: ''});
  const [showShareModal, setShowShareModal] = useState(false);
  const [linkCopied, setLinkCopied] = useState(false);

  const fetchFriends = async () => {
    try {
      const apiBaseUrl = getApiBaseUrl();
      const response = await fetch(`${apiBaseUrl}/api/friends`, {
        headers: { 'Authorization': `Bearer ${localStorage.getItem('token')}` }
      });
      if (response.ok) {
        const friendsData = await response.json();
        setFriends(friendsData.map((f: any) => f.id));
      }
    } catch (error) {
      console.error('Error fetching friends:', error);
    }
  };

  const sendFriendRequest = async (friendId: string) => {
    try {
      const apiBaseUrl = getApiBaseUrl();
      const response = await fetch(`${apiBaseUrl}/api/friends/request`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({ friendId })
      });

      if (response.ok) {
        alert('Friend request sent successfully!');
      } else {
        const error = await response.json();
        alert(error.error || 'Failed to send friend request');
      }
    } catch (error) {
      alert('Failed to send friend request');
    }
  };

  const openReportModal = (participant: Participant) => {
    setReportingUser(participant);
    setReportData({reason: '', description: ''});
    setShowReportModal(true);
  };

  const submitReport = async () => {
    if (!reportingUser || !reportData.reason) {
      alert('Please select a reason for the report');
      return;
    }

    try {
      const apiBaseUrl = getApiBaseUrl();
      const response = await fetch(`${apiBaseUrl}/api/reports`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        },
        body: JSON.stringify({
          reportedUserId: reportingUser.id,
          gameId: gameId,
          reason: reportData.reason,
          description: reportData.description
        })
      });

      if (response.ok) {
        alert('Report submitted successfully!');
        setShowReportModal(false);
        setReportingUser(null);
        setReportData({reason: '', description: ''});
      } else {
        const error = await response.json();
        alert(error.error || 'Failed to submit report');
      }
    } catch (error) {
      alert('Failed to submit report');
    }
  };

  const getShareLink = () => {
    return `${window.location.origin}/game/${gameId}`;
  };

  const copyToClipboard = async () => {
    try {
      await navigator.clipboard.writeText(getShareLink());
      setLinkCopied(true);
      setTimeout(() => setLinkCopied(false), 2000);
    } catch (err) {
      // Fallback for older browsers
      const textArea = document.createElement('textarea');
      textArea.value = getShareLink();
      document.body.appendChild(textArea);
      textArea.select();
      document.execCommand('copy');
      document.body.removeChild(textArea);
      setLinkCopied(true);
      setTimeout(() => setLinkCopied(false), 2000);
    }
  };

  const shareGame = async () => {
    if (navigator.share) {
      try {
        await navigator.share({
          title: game?.title || 'Pick Up Game',
          text: `Join me for a game of ${game?.sport} at ${game?.location}!`,
          url: getShareLink(),
        });
      } catch (err) {
        // User cancelled sharing or error occurred
        console.log('Error sharing:', err);
      }
    } else {
      // Fallback to show share modal
      setShowShareModal(true);
    }
  };

  useEffect(() => {
    const apiBaseUrl = getApiBaseUrl();
    const newSocket = io(apiBaseUrl);
    setSocket(newSocket);

    const setupSocket = () => {
      // Join game room with user info for chat
      newSocket.emit('joinGameRoom', {
        gameId,
        userId: user?.id,
        username: user?.username
      });

      newSocket.on('user-joined', (data) => {
        setParticipants(prev => [...prev, data.user]);
      });

      newSocket.on('user-left', (data) => {
        setParticipants(prev => prev.filter(p => p.id !== data.user.id));
      });

      newSocket.on('message', (data) => {
        // Handle messages if needed in the future
        console.log('Message received:', data);
      });
    };

    const fetchGameDetails = async () => {
      try {
        const response = await fetch(`${apiBaseUrl}/api/games/${gameId}`);
        if (response.ok) {
          const game = await response.json();
          setGame(game);
        } else if (response.status === 404) {
          setError('Game not found');
        } else {
          setError('Failed to load game details');
        }
      } catch (error) {
        setError('Failed to load game details');
      }
    };

    const fetchParticipants = async () => {
      try {
        const response = await fetch(`${apiBaseUrl}/api/games/${gameId}/participants`);
        if (response.ok) {
          const data = await response.json();
          setParticipants(data);
        }
      } catch (error) {
        console.error('Error fetching participants:', error);
      } finally {
        setLoading(false);
      }
    };

    setupSocket();
    fetchGameDetails();
    fetchParticipants();
    fetchFriends();

    return () => {
      newSocket.emit('leaveGameRoom', gameId);
      newSocket.disconnect();
    };
  }, [gameId]);

  const leaveGame = async () => {
    try {
      const apiBaseUrl = getApiBaseUrl();
      const response = await fetch(`${apiBaseUrl}/api/games/${gameId}/leave`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('token')}`
        }
      });

      if (response.ok) {
        navigate('/');
      }
    } catch (error) {
      console.error('Error leaving game:', error);
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-blue-500"></div>
      </div>
    );
  }

  if (error || !game) {
    return (
      <div className="max-w-4xl mx-auto">
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-md">
          {error || 'Game not found'}
        </div>
        <button
          onClick={() => navigate('/')}
          className="mt-4 inline-flex items-center px-4 py-2 border border-gray-300 rounded-md text-sm font-medium text-gray-700 bg-white hover:bg-gray-50"
        >
          <ArrowLeft className="w-4 h-4 mr-2" />
          Back to Dashboard
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto">
      <div className="mb-6">
        <button
          onClick={() => navigate('/')}
          className="inline-flex items-center text-sm text-gray-600 hover:text-gray-900 mb-4"
        >
          <ArrowLeft className="w-4 h-4 mr-2" />
          Back to Dashboard
        </button>

        <div className="bg-white rounded-lg shadow-md p-6 mb-6">
          <div className="flex items-center justify-between mb-4">
            <div>
              <div className="flex items-center space-x-2">
                <h1 className="text-2xl font-bold text-gray-900">{game.title}</h1>
                {game.is_private && (
                  <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-purple-100 text-purple-800">
                    <Lock className="w-3 h-3 mr-1" />
                    Private
                  </span>
                )}
              </div>
              <p className="text-gray-600 capitalize">{game.sport}</p>
            </div>
            <div className="flex items-center space-x-2">
              <button
                onClick={shareGame}
                className="inline-flex items-center px-4 py-2 border border-blue-300 text-sm font-medium rounded-md text-blue-700 bg-white hover:bg-blue-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
              >
                <Share2 className="w-4 h-4 mr-2" />
                Share Game
              </button>
              <button
                onClick={leaveGame}
                className="inline-flex items-center px-4 py-2 border border-red-300 text-sm font-medium rounded-md text-red-700 bg-white hover:bg-red-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500"
              >
                <UserMinus className="w-4 h-4 mr-2" />
                Leave Game
              </button>
              {user && game && user.username === game.creator_name && (
                <button
                  onClick={() => setShowCompleteModal(true)}
                  className="inline-flex items-center px-4 py-2 border border-green-300 text-sm font-medium rounded-md text-green-700 bg-white hover:bg-green-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500"
                >
                  Complete Game
                </button>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
            <div className="flex items-center text-sm text-gray-600">
              <MapPin className="w-4 h-4 mr-2" />
              {game.location}
            </div>
            <div className="flex items-center text-sm text-gray-600">
              <Users className="w-4 h-4 mr-2" />
              {participants.length}/{game.max_players} players
            </div>
            <div className="flex items-center text-sm text-gray-600">
              <Calendar className="w-4 h-4 mr-2" />
              {formatDate(game.created_at)}
            </div>
            {game.min_age && game.min_age > 0 && (
              <div className="flex items-center text-sm text-gray-600">
                <span className="w-4 h-4 mr-2 text-center text-xs font-bold">18+</span>
                Min Age: {game.min_age}
              </div>
            )}
            {game.is_money_game && (
              <div className="flex items-center text-sm text-gray-600">
                <span className="w-4 h-4 mr-2 text-center text-xs font-bold">💰</span>
                Entry: ${game.entry_fee} | Pot: ${game.total_pot}
              </div>
            )}
          </div>

          {participants.length >= game.max_players && (
            <div className="bg-green-50 border border-green-200 text-green-700 px-4 py-3 rounded-md">
              🎉 Game is full! Ready to start playing!
            </div>
          )}
        </div>

        {/* Two-column layout for participants and chat */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {/* Participants Section */}
          <div className="bg-white rounded-lg shadow-md p-6">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-semibold text-gray-900">Players ({participants.length})</h2>
              <div className="flex items-center text-sm text-gray-500">
                <UserPlus className="w-4 h-4 mr-1" />
                {participants.length === 0 ? 'No players yet' : `${participants.length} joined`}
              </div>
            </div>

            {participants.length === 0 ? (
              <div className="text-center py-8">
                <Users className="mx-auto h-12 w-12 text-gray-400 mb-4" />
                <p className="text-gray-500">No players have joined yet. Be the first!</p>
              </div>
            ) : (
              <div className="space-y-3">
                {participants.map((participant, index) => (
                  <div
                    key={participant.id}
                    className="flex items-center justify-between p-3 bg-gray-50 rounded-lg"
                  >
                    <div className="flex items-center">
                      <div className="w-8 h-8 bg-blue-500 rounded-full flex items-center justify-center text-white text-sm font-medium">
                        {participant.username.charAt(0).toUpperCase()}
                      </div>
                      <div className="ml-3">
                        <p className="text-sm font-medium text-gray-900">{participant.username}</p>
                        <p className="text-xs text-gray-500">Joined {formatDate(participant.joined_at)}</p>
                      </div>
                    </div>
                    <div className="flex items-center space-x-2">
                      {index === 0 && (
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800">
                          Host
                        </span>
                      )}
                      {user && participant.id !== user.id && !friends.includes(participant.id) && (
                        <button
                          onClick={() => sendFriendRequest(participant.id)}
                          className="inline-flex items-center px-2 py-1 text-xs font-medium text-blue-600 hover:text-blue-800"
                          title="Add as friend"
                        >
                          <UserPlus className="w-3 h-3 mr-1" />
                          Add Friend
                        </button>
                      )}
                      {user && participant.id !== user.id && friends.includes(participant.id) && (
                        <span className="inline-flex items-center px-2 py-1 text-xs font-medium text-green-600">
                          <UserCheck className="w-3 h-3 mr-1" />
                          Friend
                        </span>
                      )}
                      {user && participant.id !== user.id && (
                        <button
                          onClick={() => openReportModal(participant)}
                          className="inline-flex items-center px-2 py-1 text-xs font-medium text-red-600 hover:text-red-800"
                          title="Report player"
                        >
                          <Flag className="w-3 h-3 mr-1" />
                          Report
                        </button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Chat Section */}
          <div>
            <Chat gameId={gameId!} socket={socket} />
          </div>
        </div>
      </div>
      {/* Complete Game Modal */}
      {showCompleteModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-40">
          <div className="bg-white rounded-lg shadow-lg p-6 w-full max-w-lg">
            <h2 className="text-xl font-bold mb-4">Complete Game: Enter Team Scores</h2>
            <form onSubmit={async (e) => {
              e.preventDefault();

              // Validate scores
              const homeScore = parseInt(results.homeScore);
              const awayScore = parseInt(results.awayScore);

              if (isNaN(homeScore) || isNaN(awayScore) || homeScore < 0 || awayScore < 0) {
                window.alert('Please enter valid scores (non-negative numbers)');
                return;
              }

              const apiBaseUrl = getApiBaseUrl();
              const payload = {
                homeScore,
                awayScore
              };
              try {
                const response = await fetch(`${apiBaseUrl}/api/games/${gameId}/complete`, {
                  method: 'POST',
                  headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${localStorage.getItem('token')}`
                  },
                  body: JSON.stringify({ results: payload })
                });
                if (response.ok) {
                  setShowCompleteModal(false);
                  window.alert('Game completed and results saved!');
                  navigate('/');
                } else {
                  const error = await response.json();
                  window.alert(error.error || 'Failed to complete game');
                }
              } catch (err) {
                window.alert('Failed to complete game');
              }
            }}>
              <div className="space-y-4">
                <div className="flex items-center justify-between space-x-4">
                  <div className="flex-1">
                    <label className="block text-sm font-medium text-gray-700 mb-2">Home Team Score</label>
                    <input
                      type="number"
                      placeholder="0"
                      value={results.homeScore}
                      onChange={e => setResults(r => ({...r, homeScore: e.target.value}))}
                      className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                      required
                      min="0"
                    />
                  </div>
                  <div className="text-2xl font-bold text-gray-500">vs</div>
                  <div className="flex-1">
                    <label className="block text-sm font-medium text-gray-700 mb-2">Away Team Score</label>
                    <input
                      type="number"
                      placeholder="0"
                      value={results.awayScore}
                      onChange={e => setResults(r => ({...r, awayScore: e.target.value}))}
                      className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                      required
                      min="0"
                    />
                  </div>
                </div>
                <div className="text-center text-sm text-gray-600">
                  Final Score: {results.homeScore || '0'} - {results.awayScore || '0'}
                </div>
              </div>
              <div className="flex justify-end mt-6 space-x-2">
                <button type="button" onClick={() => setShowCompleteModal(false)} className="px-4 py-2 border rounded text-gray-700">Cancel</button>
                <button type="submit" className="px-4 py-2 bg-green-600 text-white rounded">Submit Results</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Report Player Modal */}
      {showReportModal && reportingUser && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-40">
          <div className="bg-white rounded-lg shadow-lg p-6 w-full max-w-lg">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold">Report Player: {reportingUser.username}</h2>
              <button
                onClick={() => setShowReportModal(false)}
                className="text-gray-400 hover:text-gray-600"
              >
                <X className="w-6 h-6" />
              </button>
            </div>

            <form onSubmit={(e) => {
              e.preventDefault();
              submitReport();
            }}>
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Reason for Report *
                  </label>
                  <select
                    value={reportData.reason}
                    onChange={(e) => setReportData(prev => ({...prev, reason: e.target.value}))}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                    required
                  >
                    <option value="">Select a reason</option>
                    <option value="inappropriate_behavior">Inappropriate Behavior</option>
                    <option value="harassment">Harassment</option>
                    <option value="cheating">Cheating</option>
                    <option value="unsportsmanlike_conduct">Unsportsmanlike Conduct</option>
                    <option value="no_show">No Show</option>
                    <option value="other">Other</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Additional Details (Optional)
                  </label>
                  <textarea
                    value={reportData.description}
                    onChange={(e) => setReportData(prev => ({...prev, description: e.target.value}))}
                    placeholder="Please provide additional details about the incident..."
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                    rows={4}
                  />
                </div>
              </div>

              <div className="flex justify-end mt-6 space-x-2">
                <button
                  type="button"
                  onClick={() => setShowReportModal(false)}
                  className="px-4 py-2 border border-gray-300 rounded-md text-gray-700 hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700"
                >
                  Submit Report
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Share Game Modal */}
      {showShareModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-40">
          <div className="bg-white rounded-lg shadow-lg p-6 w-full max-w-lg">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold">Share Game</h2>
              <button
                onClick={() => setShowShareModal(false)}
                className="text-gray-400 hover:text-gray-600"
              >
                <X className="w-6 h-6" />
              </button>
            </div>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Game Link
                </label>
                <div className="flex items-center space-x-2">
                  <input
                    type="text"
                    value={getShareLink()}
                    readOnly
                    className="flex-1 px-3 py-2 border border-gray-300 rounded-md bg-gray-50 text-sm"
                  />
                  <button
                    onClick={copyToClipboard}
                    className="inline-flex items-center px-3 py-2 border border-gray-300 rounded-md text-sm font-medium text-gray-700 bg-white hover:bg-gray-50"
                  >
                    {linkCopied ? (
                      <>
                        <Check className="w-4 h-4 mr-1" />
                        Copied!
                      </>
                    ) : (
                      <>
                        <Copy className="w-4 h-4 mr-1" />
                        Copy
                      </>
                    )}
                  </button>
                </div>
              </div>

              <div className="bg-gray-50 rounded-lg p-4">
                <h3 className="text-sm font-medium text-gray-900 mb-2">Game Details</h3>
                <div className="text-sm text-gray-600 space-y-1">
                  <p><strong>Title:</strong> {game?.title}</p>
                  <p><strong>Sport:</strong> {game?.sport}</p>
                  <p><strong>Location:</strong> {game?.location}</p>
                  <p><strong>Players:</strong> {participants.length}/{game?.max_players}</p>
                </div>
              </div>

              <div className="text-sm text-gray-600">
                <p>Share this link with friends to invite them to join the game!</p>
              </div>
            </div>

            <div className="flex justify-end mt-6">
              <button
                onClick={() => setShowShareModal(false)}
                className="px-4 py-2 border border-gray-300 rounded-md text-gray-700 hover:bg-gray-50"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default GameLobby;
